CREATE TABLE PARAMETROS(CD_FILIAL DOUBLE PRECISION);
CREATE TABLE ENTREGAS(CD_VENDA DOUBLE PRECISION, CD_FILIAL DOUBLE PRECISION, CD_CLIENTE DOUBLE PRECISION, NOME VARCHAR(100), BAIRRO VARCHAR(100), DATA DATE, STATUS VARCHAR(1), CD_ENTREGADOR DOUBLE PRECISION, HORA_SAIDA TIME, HORA_CHEGADA TIME, ENVIADO VARCHAR(1), ID_OPERADOR_CAIXA_ORIGINAL DOUBLE PRECISION DEFAULT 0);
CREATE TABLE VENDAS(CD_VENDA DOUBLE PRECISION, CD_FILIAL DOUBLE PRECISION, CD_CLIENTE DOUBLE PRECISION, ID_PRODUTO DOUBLE PRECISION, ORDEM DOUBLE PRECISION, CD_PRODUTO VARCHAR(6), ID_VENDA VARCHAR(13), DATA_CAIXA DATE, HORA TIME, TEMPENDERECO VARCHAR(200), TEMPREFERENCIA VARCHAR(100), STATUS VARCHAR(1), CONCLUIDO VARCHAR(1), ENTREGA VARCHAR(1), TIPO_VENDA VARCHAR(1), TROCA VARCHAR(1), PRECO_TOTAL DOUBLE PRECISION, HORAFINAL TIME, CHEQUE VARCHAR(100));
CREATE TABLE CLIENTES(CD_CLIENTE DOUBLE PRECISION NOT NULL, CD_FILIAL DOUBLE PRECISION NOT NULL, FONE VARCHAR(30), PRIMARY KEY(CD_CLIENTE,CD_FILIAL));
CREATE TABLE VENDEDORES(CD_VENDEDOR DOUBLE PRECISION PRIMARY KEY, CD_FILIAL DOUBLE PRECISION, NOME VARCHAR(100), TIPO_FUNCIONARIO VARCHAR(1), STATUS VARCHAR(1));
CREATE TABLE DELIVERYLOG(ID INTEGER NOT NULL, CD_VENDA DOUBLE PRECISION, ACTION VARCHAR(20), LOGDATE TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE CAIXA(CD_VENDA DOUBLE PRECISION, CD_FILIAL DOUBLE PRECISION, ID_OPERADORCAIXA DOUBLE PRECISION, VALOR DOUBLE PRECISION);
